const ent = $input.first().json;
const clientes = Array.isArray(ent.clientes) ? ent.clientes : [];
// Sem nenhum cliente, algo deu errado no Base44: para aqui, sem marcar ninguém como fora da base.
if (!clientes.length) throw new Error('O Base44 devolveu a lista de clientes vazia.');
const linha = (s) => (s == null ? null : String(s).replace(/\s+/g, ' ').trim() || null);
const vistos = new Set();
const linhas = [];
for (const c of clientes) {
  const pessoa = linha(c.cliente_id);
  if (!pessoa) continue;
  const ids = Array.isArray(c.ids) && c.ids.length ? c.ids : [pessoa];
  for (const id of [pessoa, ...ids]) {
    const conta = linha(id);
    if (!conta || vistos.has(conta)) continue;
    vistos.add(conta);
    linhas.push({
      conta_id: conta,
      pessoa_id: pessoa,
      nome_completo: linha(c.nome_completo),
      primeiro_nome: linha(c.primeiro_nome),
      categoria: linha(c.categoria),
      assessor: linha(c.assessor),
      celular: linha(c.celular),
      tipo_cliente: linha(c.tipo_cliente),
    });
  }
}
return [{ json: { pessoas: clientes.length, contas: linhas.length, payload: JSON.stringify(linhas) } }];
